$_MODULE['<{opartstat}prestashop>help_774efad75fe4a9da1b364762d29ce4c6'] = 'Pourquoi les données de trafic sont-elles limitées ?';
$_MODULE['<{opartstat}prestashop>help_6a851eea98ef40f89854734cf1f5b1ba'] = 'Les données de trafic sont limitées pour éviter la saturation de votre base de données.';
$_MODULE['<{opartstat}prestashop>help_af4d4a3d8dde9a86b5dfcaebd519a00a'] = 'Vous pouvez augmenter l\'espace alloué aux données de trafic en modifiant la valeur du paramètre \"Nombre maximum de visites stockées en base de données\" dans la configuration du module.';
$_MODULE['<{opartstat}prestashop>help_6e97c1b290bffedd06d4357b59252a8b'] = 'Attention : notez qu\'une valeur trop grande peut réduire les performances de votre magasin.';
$_MODULE['<{opartstat}prestashop>help_af28a4d25b01efb9c135920103706dd5'] = 'Si vous souhaitez augmenter considérablement la taille des données de trafic, vous pouvez [1]souscrire à Op\'art Stat Premium[/1]';
$_MODULE['<{opartstat}prestashop>help_d7eb27d5aea8b1ed0d18fd9924ec4eed'] = 'Le module n\'affiche aucune donnée pourquoi ? ';
$_MODULE['<{opartstat}prestashop>help_1665c3ff377b6dab281375dcfc117dbe'] = 'Par défaut, le module utilise la date de facturation.';
$_MODULE['<{opartstat}prestashop>help_00bb189e55f9f8b1db2ab2c743a955e0'] = 'Si votre Prestashop ne génère pas de facture ou si la date de facture n\'est pas définie dans la base de données, le module ne peut pas trouver de données';
$_MODULE['<{opartstat}prestashop>help_8741717f073c229171b3f52b6599886c'] = 'Dans ce cas, allez dans la configuration du module et cochez l\'option \"Utiliser la date de création de la commande plutôt que la date de facturation\".';
$_MODULE['<{opartstat}prestashop>help_404cb66a30190dbe11aa4320f64cd36a'] = 'Le module ne semble pas prendre en compte toutes les commandes, pourquoi ?';
$_MODULE['<{opartstat}prestashop>help_3dc4ec39b9bbcb634b11cf0bf9f99e1f'] = 'Vérifiez que vous avez coché tous les statuts de commande corrects dans la configuration du module';
$_MODULE['<{opartstat}prestashop>help_777a955663fb8b8f4daa4943b48cd1c8'] = 'Voici un exemple de statuts courants pour les commandes valides : Livré, Expédié, Paiement accepté';
$_MODULE['<{opartstat}prestashop>help_e6e420ad4ed82de14671c7e9b017b6f1'] = 'Faites de même pour les commandes remboursées et les commandes en cours (non réglées)';
$_MODULE['<{opartstat}prestashop>help_c2050d05df08658ccc762f5e4ae0847b'] = 'Notez que le statut \"remboursement partiel\" doit être coché pour les commandes valides, vous trouverez plus d\'explications ci-dessous';
$_MODULE['<{opartstat}prestashop>help_f4da9ec7753b1177db82c0cf6eac544e'] = 'Pourquoi le statut \"remboursement partiel\" doit-il être coché pour les commandes valides ?';
$_MODULE['<{opartstat}prestashop>help_1aa83a5347e63950815c547b11b9d687'] = 'Parce qu\'une commande contenant des produits remboursés est toujours une commande valide';
$_MODULE['<{opartstat}prestashop>help_8c3e7fdadf2a0aad3cdf418b75cebcbb'] = 'Les commandes partiellement remboursées doivent être considérées comme valides pour être correctement prises en compte dans les divers calculs.';
$_MODULE['<{opartstat}prestashop>help_fac48b576e8417a04a6d9a3df99a7bba'] = 'Mais ne vous inquiétez pas, les produits remboursés seront ajoutés à votre remboursement total et non ajoutés à vos revenus ou bénéfices totaux ';
$_MODULE['<{opartstat}prestashop>help_13b0d9b8561e531f57b617924b757859'] = 'Pourquoi ai-je une valeur dans la métrique remboursement mais 0 commande remboursée ?';
$_MODULE['<{opartstat}prestashop>help_69bbb79a814a74a44302207f1a9da93d'] = 'Parce que la métrique remboursement prend en compte les remboursements partiels et les commandes totalement remboursée alors que le nombre de remboursements ne prend en compte que les commandes totalement remboursée.';
$_MODULE['<{opartstat}prestashop>help_b540ca47429a798718c01e624dc8abeb'] = 'Comment vérifier que les données fournies par le module sont correctes ?';
$_MODULE['<{opartstat}prestashop>help_95d3834f1b39073420940707641de718'] = 'Le module a été testé sur de nombreux magasins, nous sommes donc confiants que les données qu\'il affiche sont précises.';
$_MODULE['<{opartstat}prestashop>help_389564d9e9bf90f28f16762f538cba6c'] = 'Mais si vous voulez être sûr que le module fournit des données correctes, voici les étapes à suivre pour vérifier, par exemple, les revenus globaux :';
$_MODULE['<{opartstat}prestashop>help_53e18e415e17fdc65e7d0de3942b4044'] = 'Tout d\'abord, choisissez une courte période de temps pour limiter le nombre de données que vous devrez vérifier.';
