$_MODULE['<{opartstat}prestashop>help_13f51fe451f187935338f616d1d8de21'] = 'Accédez à la page d\'administration de votre commande et filtrez vos commandes en utilisant la même période de temps.';
$_MODULE['<{opartstat}prestashop>help_e828d0182449e9368e53c87c743a2d90'] = 'Ouvrez chaque commande.';
$_MODULE['<{opartstat}prestashop>help_5b293dc66ee511a0cefcd96c338888ce'] = 'Pour chaque commande, ouvrez chaque produit qu\'elle contient.';
$_MODULE['<{opartstat}prestashop>help_519aecb9bc19e645a5d677ec6e7f4802'] = 'Multipliez la quantité de chaque produit par son prix hors taxe.';
$_MODULE['<{opartstat}prestashop>help_7d1e7aca7016cfa3965b2b176fb932a7'] = 'Ajoutez toutes les valeurs obtenues.';
$_MODULE['<{opartstat}prestashop>help_cb9e974a7aad60cba2c911848f2cf986'] = 'Le total devrait être le même que la valeur fournie par le module.';
$_MODULE['<{opartstat}prestashop>help_066fcfaf8580a3935b9a340df601bae1'] = 'Comment les ventes sont-elles attribuées aux sources de trafic, campagnes, etc ?';
$_MODULE['<{opartstat}prestashop>help_53877f8f6fc042b43b8122be117394ea'] = 'Le module utilise la méthode du \"first click\" pour attribuer une conversion. Cette méthode attribue la conversion à la première visite effectuée dans un laps de temps donnés (par défaut 72 heures) avant que la commande n\'ait été passée.';
$_MODULE['<{opartstat}prestashop>help_436b018a4ff06f8367785deb64f54d37'] = 'Si, dans les 72 heures qui précède sa commande, un utilisateur découvre votre site pour la première fois via Google. C’est Google qui se verra attribuer la conversion, même si, entre temps, il est revenu sur votre site via d\'autres sources (comme Facebook, etc.)';
$_MODULE['<{opartstat}prestashop>help_3530160d26c79580428337074a636b65'] = 'Vous pouvez modifier le laps de temps pour attribuer une conversion dans la configuration du module, en vous rendant sur l’onglet \"réglages généraux\" / \"Durée d\'attribution des conversions (en heures)\".';
$_MODULE['<{opartstat}prestashop>help_4afd24d4113ea9061ca58555d32a823b'] = 'Je viens de m’inscrire à Op’art Stat Premium, mais je n’ai aucune données Google Ads, pourquoi ?';
$_MODULE['<{opartstat}prestashop>help_5d0a2a23d07d9851f5db3489c4d7f4f0'] = 'C\'est normal 😉.';
$_MODULE['<{opartstat}prestashop>help_d408fe2f6a64501e1ecfe6aca5e19bda'] = 'Google Ads impose deux limitations concernant la récupération des données :';
$_MODULE['<{opartstat}prestashop>help_4555601dc89929c1fd7b7c632662f371'] = 'On ne peut récupérer que 90 jours d’historique à la fois.';
$_MODULE['<{opartstat}prestashop>help_85d16547589d13a36b937316b3306181'] = 'Le nombre de données que l\'on peut récupérer à chaque appel est restreint.';
$_MODULE['<{opartstat}prestashop>help_ba9b05214a5f437764c188cc29e6fc2c'] = 'Op\'art Stat va donc récupérer toutes les 10 minutes un lot de données jusqu\'à avoir récupéré l\'intégralité des 90 derniers jours.';
$_MODULE['<{opartstat}prestashop>help_96546ab292c1123d31e3e0f2b92e2d00'] = 'Ensuite, toutes les nuits à 3:00 du matin, Op\'art Stat récupèrera les données de la veille.';
$_MODULE['<{opartstat}prestashop>help_bae7ec603cf193f718e69e5d1f993bbd'] = 'Donc, d’ici demain, le module devrait avoir récupéré les 90 jours d’historique et pourra y ajouter chaque nouvelle journée.';
$_MODULE['<{opartstat}prestashop>help_8883b3d2f10ab09739a146303be8ca28'] = 'Vous pourrez ainsi consulter les 90 derniers jours de vos données Google Ads, et chaque jour suivant ajoutera une journée supplémentaire, soit 91, 92, 93 jours, et ainsi de suite.';
$_MODULE['<{opartstat}prestashop>help_a58cfa819380d8d28cecc70fc4530a47'] = 'Les données de CA et de conversions ne correspondent pas à celles indiquées dans mon compte Google Ads, pourquoi ?';
$_MODULE['<{opartstat}prestashop>help_865c7a4bcf8d00429764ed7dd39e783b'] = 'Op’art Stat n\'utilise pas les conversions fournies par Google Ads, il utilise son propre mode de calcul, pour deux raisons.';
$_MODULE['<{opartstat}prestashop>help_116eb887906a9686026544dbd4ae18cb'] = 'Premièrement, Google à tout intérêt à vous dire qu’il génère beaucoup de revenu pour que vous continuiez d’investir. ';
$_MODULE['<{opartstat}prestashop>help_611b28e3d26127933313de0b79772892'] = 'Deuxièmement, les conversions indiquées par Google Ads sont obligatoirement supérieures à ce qu’elle devrait, car GoogleAds ne connait pas votre historique de visites (contrairement à Op’art Stat) !';
$_MODULE['<{opartstat}prestashop>help_a9dfeb4bd0222e37e92f9176c87de423'] = 'Donc, s’il voit une commande liée à un clic sur une de ses pubs alors FORCEMENT la conversion lui revient.';
$_MODULE['<{opartstat}prestashop>help_e28ff7f7205a2bf3b312cc956a818c28'] = 'Prenons un exemple si :';
$_MODULE['<{opartstat}prestashop>help_0f66440222b0f8b7f77bff5c8909fa03'] = '➡ le lundi, Louis découvre votre site via Pinterest.';
$_MODULE['<{opartstat}prestashop>help_920a2de95d2270e408bd0461df1d6add'] = '➡ le mardi, il clique sur une pub GoogleAds';
$_MODULE['<{opartstat}prestashop>help_b5db0103c9e97e201bd9ee991a2b6563'] = '➡ le mercredi, il passe commande.';
$_MODULE['<{opartstat}prestashop>help_b11ae3a43431460d5b355ac680b21aef'] = 'C’est Pinterest qui a fait découvrir votre site, c’est donc à lui qu’il faut attribuer la conversion. 🏆';
$_MODULE['<{opartstat}prestashop>help_75e3a2c2e4340a0ebbfdf01e17301c7c'] = 'Mais GoogleAds ne sait pas qu’il y a eu une visite depuis Pinterest.';
$_MODULE['<{opartstat}prestashop>help_fda8106a6c9c8de253deab618df696b7'] = 'Pour lui, la première visite, est celle générée par GoogleAds et il va donc s’attribuer la vente.';
$_MODULE['<{opartstat}prestashop>help_df315ce2a6bc63ab2656ca373449aaac'] = 'C’est pour cette raison que le module attribue lui-même les conversions et toutes les valeurs qui en découlent sont ainsi bien plus objectives.';
